/**
 * What Kinextion has learned about what you'll actually do.
 *
 * The feedback loop is only worth having if the user can see it working, and
 * the fastest way to lose trust in a "personalised" system is for it to claim
 * a preference you don't recognise. So this screen shows the conclusions and
 * the evidence side by side: every line here is generated by the same function
 * that feeds the recommendation generator, and every one carries the count it
 * was drawn from. If it says you skip evening suggestions, you can scroll down
 * and count the evenings.
 */

import { useCallback, useEffect, useState } from "react";
import { RefreshControl, ScrollView, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { Stack } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import Animated, { FadeInDown } from "react-native-reanimated";
import { WELLNESS_LABELS } from "@kinextion/shared";

import { AuroraBackdrop, Card, EmptyState, ScreenHeader, Txt } from "../../components/ui";
import { useApi } from "../../hooks/useApi";
import type { RecommendationHistory, RemoteRecommendation } from "../../services";
import { categoryColor, color, radius, space, tint, type Category } from "../../theme";

export default function RecommendationsScreen() {
  const api = useApi();
  const [history, setHistory] = useState<RecommendationHistory | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [failed, setFailed] = useState(false);

  const load = useCallback(async () => {
    try {
      setHistory(await api.listRecommendations(50));
      setFailed(false);
    } catch {
      setFailed(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    void load().finally(() => setRefreshing(false));
  }, [load]);

  const prefs = history?.preferences;
  const answered = prefs?.answered ?? 0;

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: color.bg }} edges={["bottom"]}>
      <Stack.Screen
        options={{
          title: "What it's learned",
          headerStyle: { backgroundColor: color.bg },
          headerShadowVisible: false,
          headerTintColor: color.text,
          headerBackTitle: "Back",
        }}
      />
      <AuroraBackdrop accent={color.pink} />

      <ScrollView
        contentContainerStyle={{ padding: space.xl, paddingBottom: space.xxxl }}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            tintColor={color.textFaint}
          />
        }
      >
        <ScreenHeader
          title="What it's learned"
          subtitle="Built from what you did with past suggestions — nothing else."
        />

        {failed ? (
          <EmptyState
            icon="cloud-offline-outline"
            title="Couldn't load your history"
            body="Pull down to try again."
            accent={color.amber}
          />
        ) : !history ? null : (
          <>
            {/* ── The conclusions ──────────────────────────────────────── */}
            {prefs?.lines.length ? (
              <Animated.View entering={FadeInDown.duration(400)}>
                <Card accent={color.pink}>
                  <View
                    style={{
                      flexDirection: "row",
                      alignItems: "center",
                      gap: space.sm,
                    }}
                  >
                    <Ionicons name="school-outline" size={16} color={color.pink} />
                    <Txt variant="bodyStrong" c={color.pink} style={{ flex: 1 }}>
                      {prefs.provisional ? "Early read" : "Established pattern"}
                    </Txt>
                  </View>

                  <View style={{ gap: space.md, marginTop: space.lg }}>
                    {prefs.lines.map((line) => (
                      <View key={line} style={{ flexDirection: "row", gap: space.sm }}>
                        <Ionicons
                          name="analytics-outline"
                          size={14}
                          color={color.pink}
                          style={{ marginTop: 3 }}
                        />
                        <Txt variant="small" c={color.textMuted} style={{ flex: 1 }}>
                          {line}
                        </Txt>
                      </View>
                    ))}
                  </View>

                  <Txt
                    variant="small"
                    c={color.textFaint}
                    style={{ marginTop: space.lg, fontSize: 11 }}
                  >
                    {prefs.provisional
                      ? "Based on a short history, so treat it as a first impression. It sharpens as you answer more."
                      : "These are fed into every new suggestion, word for word."}
                  </Txt>
                </Card>
              </Animated.View>
            ) : (
              <NotYetLearning answered={answered} />
            )}

            {/* ── The evidence ─────────────────────────────────────────── */}
            {history.recommendations.length === 0 ? null : (
              <>
                <View
                  style={{
                    flexDirection: "row",
                    alignItems: "baseline",
                    marginTop: space.xxl,
                    marginBottom: space.md,
                  }}
                >
                  <Txt variant="heading" style={{ flex: 1 }}>
                    Every suggestion
                  </Txt>
                  {answered > 0 ? (
                    <Txt variant="small" c={color.textFaint}>
                      {prefs?.acted ?? 0} of {answered} done
                    </Txt>
                  ) : null}
                </View>

                <View style={{ gap: space.sm }}>
                  {history.recommendations.map((r, i) => (
                    <Animated.View
                      key={r.id}
                      entering={FadeInDown.duration(300).delay(Math.min(i, 8) * 40)}
                    >
                      <HistoryRow recommendation={r} />
                    </Animated.View>
                  ))}
                </View>
              </>
            )}
          </>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

/**
 * The honest state before there's enough to conclude anything.
 *
 * Names the actual number still needed rather than saying "keep going" — a
 * progress statement someone can act on beats an encouragement they can't.
 */
function NotYetLearning({ answered }: { answered: number }) {
  const NEEDED = 8;
  const remaining = Math.max(0, NEEDED - answered);

  return (
    <Card>
      <View style={{ flexDirection: "row", gap: space.md }}>
        <Ionicons
          name="hourglass-outline"
          size={18}
          color={color.textMuted}
          style={{ marginTop: 2 }}
        />
        <View style={{ flex: 1 }}>
          <Txt variant="bodyStrong">Not enough to say yet</Txt>
          <Txt variant="small" c={color.textMuted} style={{ marginTop: 4 }}>
            {answered === 0
              ? "Nothing's been answered yet. Tap “I did it” or “Something else” on a suggestion and it starts learning."
              : `You've answered ${answered}. About ${remaining} more and it can tell what actually lands for you rather than guessing.`}
          </Txt>
        </View>
      </View>
    </Card>
  );
}

function HistoryRow({ recommendation }: { recommendation: RemoteRecommendation }) {
  const accent = categoryColor[recommendation.category as Category] ?? color.textMuted;
  const answered = recommendation.acted || recommendation.dismissed;

  const status = recommendation.acted
    ? { icon: "checkmark-circle" as const, label: "Did it", tone: color.green }
    : recommendation.dismissed
      ? {
          icon: "close-circle-outline" as const,
          label: "Skipped",
          tone: color.textFaint,
        }
      : {
          icon: "ellipse-outline" as const,
          label: "No answer",
          tone: color.textFaint,
        };

  return (
    <Card padded={false} style={{ padding: space.lg, opacity: answered ? 1 : 0.6 }}>
      <View style={{ flexDirection: "row", gap: space.md }}>
        <Ionicons name={status.icon} size={17} color={status.tone} style={{ marginTop: 2 }} />
        <View style={{ flex: 1 }}>
          <Txt variant="body">{recommendation.content}</Txt>

          <View
            style={{
              flexDirection: "row",
              alignItems: "center",
              gap: space.sm,
              marginTop: space.sm,
            }}
          >
            <View
              style={{
                paddingHorizontal: space.sm,
                paddingVertical: 2,
                borderRadius: radius.pill,
                backgroundColor: tint(accent, 0.12),
              }}
            >
              <Txt variant="label" c={accent} style={{ fontSize: 9 }}>
                {WELLNESS_LABELS[recommendation.category] ?? recommendation.category}
              </Txt>
            </View>
            <Txt variant="small" c={status.tone} style={{ fontSize: 11 }}>
              {status.label}
            </Txt>
            <View style={{ flex: 1 }} />
            <Txt variant="small" c={color.textFaint} style={{ fontSize: 11 }}>
              {shortDate(recommendation.createdAt)}
            </Txt>
          </View>
        </View>
      </View>
    </Card>
  );
}

function shortDate(iso: string): string {
  const date = new Date(iso);
  const days = Math.floor((Date.now() - date.getTime()) / 86_400_000);
  if (days === 0) return "Today";
  if (days === 1) return "Yesterday";
  if (days < 7) return `${days}d ago`;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}
